export async function createConnection() {
  let isConnected = true;

  return {
    async query(sql) {
      if (!isConnected) {
        throw new Error('Connection is closed');
      }

      if (!sql || typeof sql !== 'string') {
        throw new TypeError('Query must be a non-empty string');
      }

      console.log('[sql]', sql);
      return [];
    },

    async close() {
      isConnected = false;
      console.log('[db] Connection closed');
    },

    isConnected() {
      return isConnected;
    }
  };
}

export async function createConnection(config = {}) {
  const { mockResponses = {}, logQueries Connected = true;

  return {
    async query(sql) {
      if (!isConnected) {
        throw new Error('Connection is closed');
      }

      if (logQueries) {
        console.log('[sql]', sql);
      }

      // Match mock responses by SQL pattern
      for (const [pattern, response] of Object.entries(mockResponses)) {
        if (sql.includes(pattern)) {
          return typeof response === 'function' ? response(sql) : response;
        }
      }

      return [];
    },

    async close() {
      isConnected = false;
    }
  };
}

export async function createConnection(config = {}) {
  const { enableLogging = false } = config;

  return {
    async query(sql) {
      if (enableLogging) {
        console.log('[sql]', sql);
      }
      return [];
    }
  };
}

