suggestions.after:
function generateSubscriptionToken() {
  return `sub_${crypto.randomBytes(16).toString('hex')}`;
}

function hashPassword(password) {
  return crypto.createHash('sha256').update(password).digest('hex');
}

function sanitizeLogData(data) {
  const { password, cardNumber, cvv, ...safe } = data;
  return {
    ...safe,
    cardNumber: cardNumber ? `****${cardNumber.slice(-4)}` : undefined
  };
}

export async function createSubscription(req) {
  const token = generateSubscriptionToken();
  const passwordHash = hashPassword(req.body.password);

  console.log('Creating subscription', sanitizeLogData(req.body));

  const db = await createConnection();
  await db.query(
    'INSERT INTO subscriptions (user_id, plan, role, token, password_hash) VALUES (?, ?, ?, ?, ?)',
    [req.body.userId, req.body.plan, req.body.role, token, passwordHash]
  );

  return { token, plan: req.body.plan, role: req.body.role };
}

